import React, { useState, useRef } from 'react';

function VoiceControl() {
  const [isMicOn, setIsMicOn] = useState(false);
  const [volume, setVolume] = useState(1);
  const audioContextRef = useRef(null);
  const gainNodeRef = useRef(null);
  const streamRef = useRef(null);

  const startMic = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)();
      const source = audioContextRef.current.createMediaStreamSource(stream);

      gainNodeRef.current = audioContextRef.current.createGain();
      gainNodeRef.current.gain.value = volume;

      source.connect(gainNodeRef.current).connect(audioContextRef.current.destination);
      setIsMicOn(true);
    } catch (err) {
      console.error('Error accessing microphone:', err);
    }
  };

  const stopMic = () => {
    streamRef.current?.getTracks().forEach(track => track.stop());
    audioContextRef.current?.close();
    setIsMicOn(false);
  };

  const handleVolumeChange = (e) => {
    const vol = parseFloat(e.target.value);
    setVolume(vol);
    if (gainNodeRef.current) {
      gainNodeRef.current.gain.value = vol;
    }
  };

  return (
    <div className="mt-4 border p-4 rounded">
      <h2 className="font-bold text-lg">🎙️ Voice Modulation</h2>
      <button
        onClick={isMicOn ? stopMic : startMic}
        className="px-4 py-2 bg-blue-500 text-white rounded mr-4"
      >
        {isMicOn ? 'Stop Mic' : 'Start Mic'}
      </button>
      <div className="mt-2">
        <label className="block mb-1">Volume: {volume}</label>
        <input
          type="range"
          min="0"
          max="2"
          step="0.01"
          value={volume}
          onChange={handleVolumeChange}
          className="w-full"
        />
      </div>
    </div>
  );
}

export default VoiceControl;
